  C.name.resize(40);
  for (size_t i = 0; i < C.name.size(); i++)
    {int rhs = 101 + i + 1 + offset; C.name[i] = TEST_VALUE;}
  // c_side.test_pat[character, 0, NOT]
  C.type.resize(40);
  for (size_t i = 0; i < C.type.size(); i++)
    {int rhs = 101 + i + 2 + offset; C.type[i] = TEST_VALUE;}
  // c_side.test_pat[character, 0, NOT]
  C.alias.resize(40);
  for (size_t i = 0; i < C.alias.size(); i++)
    {int rhs = 101 + i + 3 + offset; C.alias[i] = TEST_VALUE;}
  // c_side.test_pat[character, 0, NOT]
  C.component_name.resize(40);
  for (size_t i = 0; i < C.component_name.size(); i++)
    {int rhs = 101 + i + 4 + offset; C.component_name[i] = TEST_VALUE;}
